from pathlib import Path
import json,html
H=Path(__file__).resolve().parent;pub=json.loads((H/'published.json').read_text());scope=json.loads((H/'scope.json').read_text())
rows=[{k:r[k] for k in ['style','category','concept','name','gender','destination','source']} for r in pub]
for r in rows:r['url']=Path(r['destination']).as_uri();r['reference']=Path(r['source']).as_uri()
table=''.join('<tr><td>'+html.escape(s)+'</td><td>70</td><td>28</td><td>40</td><td>138</td></tr>' for s in scope['styles'])
page='''<!doctype html><html lang="en"><meta charset="utf-8"><title>Task 9 — remaining 12 People styles</title><meta name="viewport" content="width=device-width, initial-scale=1"><style>
body{font:16px system-ui,sans-serif;background:#f6f8fb;color:#192536;margin:24px auto;max-width:1400px;padding:0 20px}h1{font-size:28px}p{max-width:1000px;line-height:1.5}.summary{padding:16px 20px;background:#e1f2e8;border-radius:8px}select,input,button{font:inherit;padding:7px;border:1px solid #aab6c6;border-radius:5px}label{display:inline-block;margin:8px 20px 8px 0}#cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(300px,1fr));gap:16px}article{background:white;border:1px solid #d4dce7;border-radius:8px;padding:12px}article h2{font-size:17px;margin:4px 0}figure{margin:0}figcaption{font-size:13px;color:#526173;margin:5px}.pair{display:flex}.pair figure{flex:1;min-width:0}.pair img{width:100%;height:auto;aspect-ratio:1;background:#e7edf4}.pair .ref{display:none}body.references .ref{display:block}a{color:#1456a3}table{border-collapse:collapse;margin:12px 0}td,th{padding:6px 16px;border-bottom:1px solid #d4dce7;text-align:left}details{margin:18px 0}.controls{position:sticky;top:0;background:#f6f8fbf5;padding:8px 0;z-index:2}#count{margin:8px 0 16px}small{display:block;color:#526173}
</style><h1>Task 9 — remaining 12 People styles</h1><div class="summary"><b>1,656 symbols published · 138 per style · every result visually checked</b><p>70 Pronouns, 28 Contractions and 40 Comparatives per style. Original People and numbered Library source images are unchanged. Finished files are in each style’s new root-level category folders.</p></div>
<p>Existing full figures and poses are reused in self-contained SVG compositions. Arrows, books, punctuation and comparative details are retained. The embedded artwork remains raster artwork; these are not whole-style vector conversions.</p>
<p>The eight running/walking and strength comparison concepts have <b>one native character version per style</b>, using intact existing poses. Other applicable symbols retain male/female variants. This replaces the provisional plan to create a second action variant where suitable artwork did not exist. Some native poses have different clothing from the standing figure. Holding symbols combine the native holding pose, appropriate character head and visible hands with the preserved book; Doll’s male holding pose uses adapted arms.</p>
<details><summary>All 12 styles and counts</summary><table><thead><tr><th>Style</th><th>Pronouns</th><th>Contractions</th><th>Comparatives</th><th>Total</th></tr></thead><tbody>TABLE</tbody></table></details>
<p><a href="verification.json">Verification record</a> · <a href="published.json">Published file manifest</a> · <a href="visual_review_log.json">Visual review log</a>. Review images and staged copies have been deleted. This page reads the final Library files directly. The other saved styles’ publication work and later Task 10 are separate outstanding tasks.</p>
<div class="controls"><label>Category <select id="category"></select></label><label>Concept <select id="concept"></select></label><label>Style <select id="style"></select></label><label><input id="refs" type="checkbox"> Show existing layout reference</label><button id="prev">Previous</button> <button id="next">Next</button><div id="count"></div></div><main id="cards"></main>
<script>const rows=DATA;const cat=document.querySelector('#category'),concept=document.querySelector('#concept'),style=document.querySelector('#style'),cards=document.querySelector('#cards');function options(el,values){el.replaceChildren(...values.map(x=>new Option(x,x)))}options(cat,['Pronouns','Contractions','Comparatives']);options(style,['All 12 styles',...new Set(rows.map(r=>r.style))]);function concepts(){options(concept,[...new Set(rows.filter(r=>r.category===cat.value).map(r=>r.concept))].sort());if(cat.value==='Pronouns')concept.value='my';render()}function render(){cards.replaceChildren();const xs=rows.filter(r=>r.category===cat.value&&r.concept===concept.value&&(style.value==='All 12 styles'||r.style===style.value));document.querySelector('#count').textContent=xs.length+' finished symbols shown';for(const r of xs){const article=document.createElement('article'),h=document.createElement('h2');h.textContent=r.style+' — '+r.name;article.append(h);const pair=document.createElement('div');pair.className='pair';for(const [url,label,cl] of [[r.reference,'Existing Kawaii layout reference','ref'],[r.url,'Finished own-style figure','final']]){const fig=document.createElement('figure');fig.className=cl;const a=document.createElement('a');a.href=url;a.target='_blank';const img=document.createElement('img');img.src=url;img.loading='lazy';img.alt=r.style+' '+r.name+' '+label;a.append(img);const caption=document.createElement('figcaption');caption.textContent=label;fig.append(a,caption);pair.append(fig)}article.append(pair);if(r.gender==='native'){const note=document.createElement('small');note.textContent='One intact native action variant';article.append(note)}cards.append(article)}}cat.onchange=concepts;concept.onchange=render;style.onchange=render;document.querySelector('#refs').onchange=e=>document.body.classList.toggle('references',e.target.checked);for(const [id,step] of [['prev',-1],['next',1]])document.getElementById(id).onclick=()=>{concept.selectedIndex=(concept.selectedIndex+step+concept.options.length)%concept.options.length;render()};concepts();</script></html>'''
(H/'index.html').write_text(page.replace('TABLE',table).replace('DATA',json.dumps(rows).replace('</','<\\/')))
print(H/'index.html')
